// Used when nothing matches — stays useful rather than apologetic.
export const fallbackResponse = {
  text:
    "I don't have a prepared answer for that one yet — this is a demo mentor with a limited set of sample responses. Once the backend service is connected, this will handle open-ended questions properly.",
  tips: [
    "Try asking about DSA, resumes, interviews, aptitude or skill planning.",
    "Or pick one of the suggested questions to see a full sample response.",
  ],
};

/**
 * Picks a response for a user message by scoring each topic's keywords
 * against the message text. Longer keyword matches win, so "technical
 * interview" beats a stray match on "technical".
 *
 * This is deliberately simple string matching — NOT natural language
 * understanding. Replace this whole function with a backend call when
 * the real mentor service exists.
 */
export function getMentorReply(message) {
  const text = message.toLowerCase();
  let best = null;
  let bestScore = 0;

  for (const topic of Object.values(mentorResponses)) {
    for (const keyword of topic.keywords) {
      if (text.includes(keyword) && keyword.length > bestScore) {
        best = topic;
        bestScore = keyword.length;
      }
    }
  }

  const picked = best ?? fallbackResponse;
  return { text: picked.text, tips: picked.tips ?? [] };
}
